// Writes the demo image and its source into a TypeScript module.  SPDX-License-Identifier: MIT
import { readFileSync, writeFileSync } from 'node:fs';

const [source, image, target] = process.argv.slice(2);
const text = `/**
 * Benchtop's ESP32 demo firmware (firmware/esp32/demo.S): an image the ROM
 * boots from flash offset 0x1000.  Generated by firmware/esp32/build.sh; do
 * not edit by hand.
 */
export const ESP32_DEMO = {
  name: 'Demo: blink, button and fade',
  offset: 0x1000,
  source: ${JSON.stringify(readFileSync(source, 'utf8'))},
  image: '${readFileSync(image).toString('base64')}',
} as const;
`;
writeFileSync(target, text);
console.log(`${target}: ${text.length} characters`);
